import{_ as l,l as t,o as a,c as n,v as i,p as o,x as s,d as p,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"微内核 L4 / seL4","description":"","frontmatter":{"title":"微内核 L4 / seL4","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/microkernel-sel4.md","filePath":"cs/microkernel-sel4.md","lastUpdated":1789023840000}'),u={name:"cs/microkernel-sel4.md"};function L(h,e,_,E,P,A){const r=t("Mermaid");return a(),n("div",null,[e[1]||(e[1]=i('<h1 id="微内核-l4-sel4" tabindex="-1">微内核 L4 / seL4 <a class="header-anchor" href="#微内核-l4-sel4" aria-label="Permalink to &quot;微内核 L4 / seL4&quot;">​</a></h1><div class="epigraph"><p>微内核只把地址空间、线程、IPC 留在核内；驱动与文件系统在用户态。seL4 进一步给出形式化功能正确与隔离证明。</p><footer>—— 据 Liedtke 对 L4 的论述；Klein et al., seL4, SOSP 2009；[证明助手](/cs/proof-assistants) 为形式化先修对照</footer></div><p><a href="/cs/unikernel">unikernel</a> 把一切链进一空间。<a href="/cs/user-kernel-split">Linux</a> 是宏内核。缺口是 <strong>微内核</strong>：IPC 税与 seL4 证明范围。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>驱动崩不倒核，但每条 I/O 可能 IPC。seL4：抽象规格证明，假设硬件模型。缺口：Linux 兼容要用户态 Linux 或 personality；实时可强。本课不把证明脚本当作业。</p><p><span class="marginnote">L4 家族性能靠寄存器传短消息。对象是内核最小化，不是 Linux 发行版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户 pager 实现分页；文件系统是服务器。对照 FUSE：Linux 上的用户 FS 是亲戚。对照 <a href="/cs/gvisor">gVisor</a>：都把服务挪出核，机制不同。对照 KVM：微内核可当 hypervisor（OKL4 等）。</p>',8)),(a(),o(d,null,{default:s(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%22%5D%20--%3E%20IPC%5B%22seL4%20IPC%22%5D%0A%20%20FS%5B%22FS%20%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%20--%3E%20IPC%0A%20%20DRV%5B%22%E9%A9%B1%E5%8A%A8%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%20--%3E%20IPC%0A%20%20KER%5B%22%E5%BE%AE%E5%86%85%E6%A0%B8%22%5D%20--%3E%20CAP%5B%22%E8%83%BD%E5%8A%9B%E4%B8%8E%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>微内核把可信计算基缩小到 IPC/调度/页，用形式化（seL4）连接课程序列开头的证明助手。它不自动给你 Linux 生态。不要写成宗教。与 <a href="/cs/linux-capabilities">capabilities</a>：seL4 能力是真正权能系统，比 Linux cap 更细。</p><p>性能：IPC 快路径是一切。</p><p>实现上：证明覆盖功能正确与完整性，假设硬件转换与汇编桩。Linux 应用要跑在用户态 Linux 或兼容层。IPC 快路径用寄存器传短消息，长消息映射页。 读法上只引用<a href="/cs/unikernel">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>微内核 L4 / seL4</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有验证假设（TLB、缓存）。不保证多核证明的全部定理。下一课外核：把抽象再往下推。</p><p>版本字段会变，课序钉的是机制对象「微内核 L4 / seL4」，不是某一主线内核的结构体名。 后课默认：内核可小到 IPC+页，并可被证明。外核与库 OS 把抽象交给应用，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>L4：核内仅 IPC/线程/空间；seL4 有证明。</li><li>驱动在用户；兼容 Linux 要另做。</li><li>外核/库 OS 是下一课。</li><li>出处：Liedtke L4；Klein et al., seL4 SOSP 2009。</li></ul>',11))])}const x=l(u,[["render",L]]);export{f as __pageData,x as default};
